const input = $input.first().json;

// Очищення зайвих лапок
function c(val) {
  if (val === null || val === undefined) return val;
  if (typeof val !== 'string') return val;
  return val.replace(/^"(.*)"$/s, '$1');
}

const out = {
  // Ідентифікація
  student_id:   input.student_id,
  student_name: input.student?.name      || input.student_name,
  slack_id:     input.student?.slack_id  || input.slack_id,
  course:       input.student?.course    || input.course,
  mentor_id:    input.student?.mentor_id || input.mentor_id,

  // Сигнали
  signals: {
    last_login_days_ago:     input.computed_signals?.last_login_days_ago     ?? null,
    missed_homework_count:   input.computed_signals?.missed_homework_count   || 0,
    late_homework_count:     input.computed_signals?.late_homework_count     || 0,
    submission_timing_shift: input.computed_signals?.submission_timing_shift || false,
    last_message_days_ago:   input.computed_signals?.last_message_days_ago   ?? null,
    wrote_to_mentor:         input.computed_signals?.wrote_to_mentor         || false,
    activity_drop:           input.computed_signals?.activity_drop           || false,
  },

  // Observer
  observer: {
    signals:                     input.observer_result?.signals                     || [],
    max_severity:                input.observer_result?.max_severity                || 0,
    sentiment:                   input.observer_result?.sentiment                   || 'neutral',
    has_explicit_dropout_intent: input.observer_result?.has_explicit_dropout_intent || false,
  },

  // Analyst
  risk_score:               Number(c(String(input.risk_score || '0'))) || 0,
  risk_level:               c(input.risk_level)               || 'low',
  urgency:                  c(input.urgency)                   || 'monitor',
  student_state:            c(input.student_state)             || 'on_track',
  active_stages:            input.active_stages                || [],
  days_to_dropout_estimate: c(input.days_to_dropout_estimate)  || null,
  red_zone:                 input.red_zone                     || false,
  score_breakdown:          input.score_breakdown              || {},
  primary_drivers:          input.primary_drivers              || [],
  supporting_evidence:      input.supporting_evidence          || [],

  // Strategy
  recommended_action:        c(input.recommended_action)        || 'no_action',
  secondary_action:          c(input.secondary_action)          || null,
  priority:                  c(input.priority)                  || 'low',
  timing:                    c(input.timing)                    || 'monitor',
  expected_lift_qualitative: c(input.expected_lift_qualitative) || 'low',
  rationale:                 c(input.rationale)                 || '',

  // Communicator
  draft_message:   c(input.draft_message)   || '',
  mentor_summary:  c(input.mentor_summary)  || '',
  dashboard_label: c(input.dashboard_label) || '✅ OK',

  // HW Summary
  hw_summary: input.hw_summary || {},

  // Службові
  status:      'pending_review',
  trigger:     input.trigger || 'manual',
  analyzed_at: new Date().toISOString(),
};

// ── Fix 4: emit ONE internally-coherent record ────────────────
const lvlRank = { low: 0, medium: 1, high: 2 };
const urgRank = { monitor: 0, this_week: 1, immediate: 2 };
const maxLvl  = (a, b) => (lvlRank[b] > lvlRank[a] ? b : a);
const maxUrg  = (a, b) => (urgRank[b] > urgRank[a] ? b : a);
const scored  = Number(out.risk_score) || 0;

if (scored <= 0) {
  // No actionable deep analysis (severity gate skip / No Action / score 0)
  // -> a single clean "OK" record. No leftover this_week/struggling mush.
  out.risk_score               = 0;
  out.risk_level               = 'low';
  out.urgency                  = 'monitor';
  out.student_state            = 'on_track';
  out.priority                 = 'low';
  out.recommended_action       = 'no_action';
  out.secondary_action         = null;
  out.timing                   = 'monitor';
  out.primary_drivers          = [];
  out.supporting_evidence      = [];
  out.days_to_dropout_estimate = null;
  out.red_zone                 = false;
  out.draft_message            = '';
  out.mentor_summary           = 'Сигналів недостатньо для глибокого аналізу — студент у нормі станом на цю дату.';
  out.dashboard_label          = '✅ OK';
} else {
  // Deep analysis ran -> forbid contradictory pairs / band under-statement.
  if (out.student_state === 'disengaged') {
    out.risk_level = maxLvl(out.risk_level, 'medium');
    out.urgency    = maxUrg(out.urgency, 'this_week');
  }
  if (scored >= 70)      out.risk_level = 'high';
  else if (scored >= 40) out.risk_level = maxLvl(out.risk_level, 'medium');
}

return [{ json: out }];

const base  = $('Pull Student Context').first().json;
const shift = $('Submission Timing Shift').first().json;
const input = $('Receive student_id').first().json;
const data  = input.body || input;

// Guard: a malformed/ping request with no student_id must NOT flow to
// Save Analysis Result — it would write a NULL student_id row (the
// "17/15" residue bug). Emit nothing so the chain stops here.
const _sid = data ? (data.student_id ?? null) : null;
if (_sid === null || _sid === undefined || _sid === '') {
  return [];
}

if (!base || !base.student_id) {
  return [{
    json: {
      error:              'Student not found',
      student_id:         data.student_id,
      risk_score:         0,
      risk_level:         'low',
      recommended_action: 'no_action',
      dashboard_label:    '❓ Не знайдено'
    }
  }];
}

const msgsItem = $('Get Recent Messages').all()
  .find(r => r.json.student_id === base.student_id);
const recentMessages = msgsItem ? msgsItem.json.recent_messages || [] : [];

const avgWeekly    = (base.prev4wk_logins || 0) / 4;
const activityDrop = (base.last7_logins   || 0) < avgWeekly * 0.5;

// Honest "no activity as of date": NULL/undefined -> null (NOT 999).
// pg `date - date` is integer; .days kept only as pg-interval safety.
function daysAgo(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'object') return v.days ?? null;
  return v;
}

const lastMsgDays = daysAgo(base.last_msg_days_ago);

const rawLoginDays = daysAgo(base.last_login_days_ago);

const lastLoginDays =
  rawLoginDays === null ? null : (rawLoginDays < 0 ? 0 : rawLoginDays);

return [{
  json: {
    student_id: base.student_id,
    trigger:    data.trigger    || 'manual',
    as_of_date: data.as_of_date || '2025-08-21',
    student: {
      name:      base.name,
      slack_id:  base.slack_id,
      course:    base.course,
      mentor_id: base.mentor_id,
      status:    base.status,
    },
    computed_signals: {
      last_login_days_ago:     lastLoginDays,
      missed_homework_count:   Number(base.missed_hw)    || 0,
      late_homework_count:     Number(base.late_hw)      || 0,
      submission_timing_shift: shift.submission_timing_shift || false,
      last_message_days_ago:   lastMsgDays,
      wrote_to_mentor:         base.wrote_to_mentor      || false,
      activity_drop:           activityDrop,
      last7_logins:            Number(base.last7_logins) || 0,
      avg_weekly_logins:       avgWeekly,
    },
    recent_messages: recentMessages,
    homework_30d:    data.homework_30d || [],
  }
}];

const signals  = $('Compute All Signals').first().json;
const hwRows   = $input.all()
  .map(r => r.json)
  .filter(h => h.hw_id !== null && h.hw_id !== undefined);

return [{
  json: {
    ...signals,
    homework_30d: hwRows,
  }
}];
